import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import {
  NO_VALUE,
  PUNCH_PAYLOAD_VERSION,
  REQUEST_ENVELOPE_VERSION,
  bytesToHex,
  canonicalPunchPayload,
  canonicalPunchPayloadText,
  canonicalRequestEnvelope,
  canonicalRequestEnvelopeText,
  formatPhoneTime,
  hexToBytes,
  isPhoneTime,
  sha256Hex,
  utf8Bytes,
} from './canonical.js';
import type { RequestEnvelopeFields } from './canonical.js';
import type { AppPunchFields } from './types.js';

/** `fixtures/canonical.json`, generated by the Java `AppSignatures` tests (task 1.5). */
interface CanonicalFixture {
  punchVersion: string;
  envelopeVersion: string;
  noValue: string;
  punches: {
    name: string;
    input: AppPunchFields;
    canonical: string;
    canonicalHex: string;
    canonicalSha256: string;
  }[];
  envelopes: {
    name: string;
    input: {
      pairingId: string;
      method: 'GET' | 'POST';
      path: string;
      query: string;
      timestamp: number;
      nonce: string;
      bodyUtf8: string;
      bodyHex: string;
    };
    bodySha256: string;
    canonical: string;
    canonicalHex: string;
    canonicalSha256: string;
  }[];
}

const fixture: CanonicalFixture = JSON.parse(
  readFileSync(fileURLToPath(new URL('../fixtures/canonical.json', import.meta.url)), 'utf8'),
);

const punch: AppPunchFields = fixture.punches[0].input;

describe('canonical punch payload (SKAT-PUNCH-1)', () => {
  it('uses the fixture constants', () => {
    expect(PUNCH_PAYLOAD_VERSION).toBe(fixture.punchVersion);
    expect(REQUEST_ENVELOPE_VERSION).toBe(fixture.envelopeVersion);
    expect(NO_VALUE).toBe(fixture.noValue);
    expect(fixture.punches.length).toBeGreaterThan(0);
    expect(fixture.envelopes.length).toBeGreaterThan(0);
  });

  it.each(fixture.punches.map((p) => [p.name, p] as const))(
    'is byte-identical to the Java builder: %s',
    async (_name, c) => {
      const bytes = canonicalPunchPayload(c.input);
      expect(bytesToHex(bytes)).toBe(c.canonicalHex);
      expect(canonicalPunchPayloadText(c.input)).toBe(c.canonical);
      expect(bytes).toEqual(hexToBytes(c.canonicalHex));
      expect(await sha256Hex(bytes)).toBe(c.canonicalSha256);
    },
  );

  it('has eleven lines, no trailing newline and no coordinate field', () => {
    const text = canonicalPunchPayloadText(punch);
    const lines = text.split('\n');
    expect(lines).toHaveLength(11);
    expect(lines[0]).toBe('SKAT-PUNCH-1');
    expect(text.endsWith('\n')).toBe(false);
    expect(text).not.toMatch(/lat|lng|longitude/i);
  });

  it('writes null metres as "-" and booleans as 0/1', () => {
    const text = canonicalPunchPayloadText({
      ...punch,
      distanceMetres: null,
      accuracyMetres: null,
      offline: true,
      mock: true,
    });
    expect(text).toContain('\ndistanceMetres=-\naccuracyMetres=-\nmock=1');
    expect(text).toContain('\noffline=1\n');
  });

  it.each([
    ['pairingId', { pairingId: '67A1B2C3D4E5F60718293A4B' }],
    ['shopId', { shopId: '5f1d7c9e8b3a4f2e1d0c9b8' }],
    ['employeeId', { employeeId: 'not-an-object-id-at-all!' }],
    ['punchId uppercase', { punchId: '3F2504E0-4F89-41D3-9A0C-0305E82C3301' }],
    ['punchId without hyphens', { punchId: '3f2504e04f8941d39a0c0305e82c3301' }],
    ['phoneTime with millis', { phoneTime: '2025-04-03T03:42:07.000Z' }],
    ['phoneTime with offset', { phoneTime: '2025-04-03T09:12:07+05:30' }],
    ['phoneTime not a real instant', { phoneTime: '2025-02-30T00:00:00Z' }],
    ['negative distance', { distanceMetres: -1 }],
    ['fractional accuracy', { accuracyMetres: 12.5 }],
    ['distance above Integer.MAX_VALUE', { distanceMetres: 2_147_483_648 }],
  ] as const)('rejects a malformed field like Java does: %s', (_name, bad) => {
    expect(() => canonicalPunchPayload({ ...punch, ...bad })).toThrow();
  });
});

describe('canonical request envelope (SKAT-REQ-1)', () => {
  it.each(fixture.envelopes.map((e) => [e.name, e] as const))(
    'is byte-identical to the Java builder: %s',
    async (_name, c) => {
      const body = hexToBytes(c.input.bodyHex);
      expect(bytesToHex(utf8Bytes(c.input.bodyUtf8))).toBe(c.input.bodyHex);
      expect(await sha256Hex(body)).toBe(c.bodySha256);

      const fields: RequestEnvelopeFields = {
        pairingId: c.input.pairingId,
        method: c.input.method,
        path: c.input.path,
        query: c.input.query,
        timestamp: c.input.timestamp,
        nonce: c.input.nonce,
        body,
      };
      const bytes = await canonicalRequestEnvelope(fields);
      expect(bytesToHex(bytes)).toBe(c.canonicalHex);
      expect(await canonicalRequestEnvelopeText(fields)).toBe(c.canonical);
      expect(await sha256Hex(bytes)).toBe(c.canonicalSha256);

      // A string body is hashed as the UTF-8 bytes fetch would send.
      const fromString = await canonicalRequestEnvelope({ ...fields, body: c.input.bodyUtf8 });
      expect(bytesToHex(fromString)).toBe(c.canonicalHex);
    },
  );

  it('treats a missing body and query as empty', async () => {
    const c = fixture.envelopes.find((e) => e.input.bodyHex === '' && e.input.query === '');
    if (!c) {
      throw new Error('fixture needs an envelope case with no body and no query');
    }
    const fields: RequestEnvelopeFields = {
      pairingId: c.input.pairingId,
      method: c.input.method,
      path: c.input.path,
      timestamp: c.input.timestamp,
      nonce: c.input.nonce,
    };
    expect(await canonicalRequestEnvelopeText(fields)).toBe(c.canonical);
    expect(await canonicalRequestEnvelopeText({ ...fields, query: null, body: null })).toBe(
      c.canonical,
    );
  });

  it('accepts an injected digest for runtimes without crypto.subtle', async () => {
    const c = fixture.envelopes[0];
    const calls: Uint8Array[] = [];
    const sha256 = async (bytes: Uint8Array) => {
      calls.push(bytes);
      return hexToBytes(c.bodySha256);
    };
    const text = await canonicalRequestEnvelopeText(
      { ...c.input, body: hexToBytes(c.input.bodyHex) },
      { sha256 },
    );
    expect(text).toBe(c.canonical);
    expect(calls).toHaveLength(1);
    expect(bytesToHex(calls[0])).toBe(c.input.bodyHex);
  });

  const good = fixture.envelopes[0].input;

  it.each([
    ['method', { method: 'PUT' as unknown as 'GET' }],
    ['path without leading slash', { path: 'api/v1/hr/attendance-app/me' }],
    ['path with query', { path: '/api/v1/hr/attendance-app/punches?from=1' }],
    ['path with line break', { path: '/api/v1\n/hr' }],
    ['query with line break', { query: 'a=1\r\nb=2' }],
    ['timestamp fractional', { timestamp: 1743651727.5 }],
    ['nonce uppercase', { nonce: 'A1B2C3D4-E5F6-4A7B-8C9D-0E1F2A3B4C5D' }],
    ['pairingId too short', { pairingId: '67a1b2c3d4e5f60718293a4' }],
  ])('rejects a malformed field like Java does: %s', async (_name, bad) => {
    await expect(canonicalRequestEnvelope({ ...good, body: '', ...bad })).rejects.toThrow();
  });
});

describe('helpers', () => {
  it('sha256Hex matches the well-known digest of the empty input', async () => {
    expect(await sha256Hex(new Uint8Array(0))).toBe(
      'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855',
    );
  });

  it('hex helpers round-trip', () => {
    const bytes = new Uint8Array([0, 1, 15, 16, 127, 128, 255]);
    expect(bytesToHex(bytes)).toBe('00010f107f80ff');
    expect(hexToBytes('00010F107F80FF')).toEqual(bytes);
    expect(() => hexToBytes('abc')).toThrow();
    expect(() => hexToBytes('zz')).toThrow();
  });

  it('formatPhoneTime drops the fraction and matches the payload format', () => {
    const value = formatPhoneTime(new Date('2025-04-03T03:42:07.987Z'));
    expect(value).toBe('2025-04-03T03:42:07Z');
    expect(isPhoneTime(value)).toBe(true);
    expect(isPhoneTime('2025-04-03T03:42:07.987Z')).toBe(false);
    expect(isPhoneTime('2025-13-01T00:00:00Z')).toBe(false);
    expect(() => formatPhoneTime(new Date('nope'))).toThrow();
  });
});
